void setup();
void loop();
// Serial lab, Exercise 3: print() vs write() for 48, 49, 50, 65, 66
const int values[] = {48, 49, 50, 65, 66};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 5; i++) {
    Serial.print("print(");  Serial.print(values[i]); Serial.print(") -> ");
    Serial.print(values[i]);                    // text: "48"
    Serial.print("   write(");  Serial.print(values[i]); Serial.print(") -> ");
    Serial.write(values[i]);                    // one byte: the character with that ASCII code: '0'
    Serial.println();
  }
}
void loop() {}
// Output:  print(48) -> 48   write(48) -> 0
//          print(49) -> 49   write(49) -> 1
//          print(50) -> 50   write(50) -> 2
//          print(65) -> 65   write(65) -> A
//          print(66) -> 66   write(66) -> B
// print(v) sends the decimal digits of v as characters; write(v) sends the raw byte v.
// To ship a small number to another Arduino and read it back with Serial.read(), use write().
